import{_ as n,o as t,c as r,ah as i}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse('{"title":"24. März 2026, 20:30 Uhr: \\"Flurfunk\\", Beugehaft für Laptops und die \\"Schwarze Zellin\\"","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/2026-03-24-prozess-update-abend.md","filePath":"logbuch/2026-03-24-prozess-update-abend.md"}'),a={name:"logbuch/2026-03-24-prozess-update-abend.md"};function s(o,e,u,h,d,l){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="_24-marz-2026-20-30-uhr-flurfunk-beugehaft-fur-laptops-und-die-schwarze-zellin" tabindex="-1">24. März 2026, 20:30 Uhr: &quot;Flurfunk&quot;, Beugehaft für Laptops und die &quot;Schwarze Zellin&quot; <a class="header-anchor" href="#_24-marz-2026-20-30-uhr-flurfunk-beugehaft-fur-laptops-und-die-schwarze-zellin" aria-label="Permalink to &quot;24. März 2026, 20:30 Uhr: &quot;Flurfunk&quot;, Beugehaft für Laptops und die &quot;Schwarze Zellin&quot;&quot;">​</a></h1><p>Der heutige Verhandlungstag am Landesgericht Linz endete vor wenigen Minuten. Während August Wöginger (der Mann, der laut seinem Lebenslauf noch nie &quot;draußen&quot; in der freien Wirtschaft gearbeitet hat) weiterhin seine Unschuld beteuert, zeichneten knapp ein Dutzend Zeugen ein düsteres Bild der oberösterreichischen Finanzverwaltung.</p><h2 id="die-forensischen-erkenntnisse-des-abends" tabindex="-1">Die forensischen Erkenntnisse des Abends: <a class="header-anchor" href="#die-forensischen-erkenntnisse-des-abends" aria-label="Permalink to &quot;Die forensischen Erkenntnisse des Abends:&quot;">​</a></h2><ol><li><strong>Der &quot;Flurfunk&quot; als Gesetz:</strong> Zahlreiche Beamte bestätigten, dass die Besetzung des Finanzamts Braunau ein offenes Geheimnis war. Der ÖVP-Bürgermeister stand fest, lange bevor die Hearingkommission überhaupt zusammengetreten war. Qualifikation? Nebensache. Parteibuch? Entscheidend.</li><li><strong>Das &quot;eigenartige&quot; Ticker-Verbot:</strong> Richterin Melanie Halbig untersagte heute jegliche Live-Berichterstattung. Strafrechtler Robert Kert (WU Wien) bezeichnete dies im <em>Standard</em> als rechtlich haltlos (&quot;eigenartig&quot;). Es gibt keine gesetzliche Grundlage in der StPO für ein solches Verbot.</li><li><strong>Die investigative Frage:</strong> Wenn eine Richterin ohne gesetzliche Basis die Öffentlichkeit aussperrt, während belastende Zeugen gegen die ÖVP aussagen, müssen wir im Archiv die Frage stellen: Handelt es sich hier um eine <strong>&quot;schwarze Zellin&quot;</strong>? Dient das Verbot dem Schutz der Zeugen oder dem Schutz des Angeklagten vor der Wahrheit?</li><li><strong>Satirische Eskalation:</strong> Die <em>Tagespresse</em> berichtet bereits von Cobra-Einsätzen gegen Journalisten-Laptops, die in &quot;Beugehaft&quot; genommen wurden. Ein treffendes Bild für die absurde Angst vor Fakten im Gerichtssaal.</li></ol><h2 id="fazit" tabindex="-1">Fazit: <a class="header-anchor" href="#fazit" aria-label="Permalink to &quot;Fazit:&quot;">​</a></h2><p>Wöginger kämpft um sein politisches Überleben, während sein Nachfolger Hattmannsdorfer bereits in den Startlöchern steht. Der Prozess offenbart nicht nur Postenschacher, sondern auch eine Justizdynamik, die wir genauestens beobachten müssen.</p><hr><p><em>Vorschau: Am Freitag geht es weiter. Das Archiv bleibt wach.</em></p>',8)])])}const f=n(a,[["render",s]]);export{g as __pageData,f as default};
